#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <functional>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<int>> adj(n + 1);
    for (const vector<long long>& e : edges) adj[e[0]].push_back((int)e[1]);
    vector<int> indeg(n + 1, 0);
    for (const vector<long long>& e : edges) indeg[e[1]]++;
    priority_queue<int, vector<int>, greater<int>> heap;
    for (int v = 1; v <= n; v++) {
        if (indeg[v] == 0) heap.push(v);
    }
    vector<int> order;
    while (!heap.empty()) {
        int u = heap.top();
        heap.pop();
        order.push_back(u);
        for (int v : adj[u]) {
            indeg[v]--;
            if (indeg[v] == 0) heap.push(v);
        }
    }
    if ((long long)order.size() != n) {
        cout << "impossible\n";
    } else {
        for (size_t i = 0; i < order.size(); i++) cout << (i ? " " : "") << order[i];
        cout << "\n";
    }

    return 0;
}

