import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[][] edges = new long[(int) m][2];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }

        int nodes = (int) n;
        List<List<Integer>> adj = new ArrayList<>();
        for (int v = 0; v <= nodes; v++) adj.add(new ArrayList<>());
        for (long[] e : edges) adj.get((int) e[0]).add((int) e[1]);
        int[] indeg = new int[nodes + 1];
        for (long[] e : edges) indeg[(int) e[1]]++;
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        for (int v = 1; v <= nodes; v++) {
            if (indeg[v] == 0) heap.add(v);
        }
        List<Integer> order = new ArrayList<>();
        while (!heap.isEmpty()) {
            int u = heap.poll();
            order.add(u);
            for (int v : adj.get(u)) {
                indeg[v]--;
                if (indeg[v] == 0) heap.add(v);
            }
        }
        if (order.size() != nodes) {
            System.out.println("impossible");
        } else {
            StringBuilder out = new StringBuilder();
            for (int i = 0; i < order.size(); i++) out.append(i > 0 ? " " : "").append(order.get(i));
            System.out.println(out);
        }
    }
}
